package com.campusevents.util;
import javax.crypto.*;import javax.crypto.spec.PBEKeySpec;import java.security.*;import java.util.Base64;
public final class PasswordUtil {private static final SecureRandom RNG=new SecureRandom();private PasswordUtil(){}private static byte[] derive(char[] p,byte[] salt)throws Exception{PBEKeySpec s=new PBEKeySpec(p,salt,120000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(s).getEncoded();}finally{s.clearPassword();}}public static String hash(String p){try{byte[] salt=new byte[16];RNG.nextBytes(salt);return "pbkdf2$"+Base64.getEncoder().encodeToString(salt)+"$"+Base64.getEncoder().encodeToString(derive(p.toCharArray(),salt));}catch(Exception e){throw new IllegalStateException(e);}}public static boolean verify(String p,String h){try{String[] a=h.split("\\$");return a.length==3&&a[0].equals("pbkdf2")&&MessageDigest.isEqual(Base64.getDecoder().decode(a[2]),derive(p.toCharArray(),Base64.getDecoder().decode(a[1])));}catch(Exception e){return false;}}}
